  "interfaces": {
    "cpp": "#include <iostream>\n#include <memory>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Shape {                                  // an abstract class is C++'s interface\n    virtual ~Shape() = default;\n    virtual string name() const = 0;\n    virtual int area() const = 0;\n};\n\nstruct Rectangle : Shape {\n    int w, h;\n    Rectangle(int w, int h) : w(w), h(h) {}\n    string name() const override { return \"Rectangle\"; }\n    int area() const override { return w * h; }\n};\n\nstruct Square : Rectangle {\n    explicit Square(int s) : Rectangle(s, s) {}\n    string name() const override { return \"Square\"; }\n};\n\nstruct Triangle : Shape {\n    int b, h;\n    Triangle(int b, int h) : b(b), h(h) {}\n    string name() const override { return \"Triangle\"; }\n    int area() const override { return b * h / 2; }\n};\n\nint main() {\n    vector<unique_ptr<Shape>> shapes;\n    shapes.push_back(make_unique<Rectangle>(3, 4));\n    shapes.push_back(make_unique<Square>(5));\n    shapes.push_back(make_unique<Triangle>(6, 4));\n    int total = 0;\n    for (const auto& s : shapes) {              // a virtual call runs the real type's area()\n        cout << s->name() << \" area \" << s->area() << endl;\n        total += s->area();\n    }\n    cout << \"total \" << total << endl;\n}",
    "java": "import java.util.*;\n\npublic class Main {\n    interface Shape { String name(); int area(); }\n\n    record Rectangle(int w, int h) implements Shape {\n        public String name() { return \"Rectangle\"; }\n        public int area() { return w * h; }\n    }\n    record Square(int s) implements Shape {\n        public String name() { return \"Square\"; }\n        public int area() { return s * s; }\n    }\n    record Triangle(int b, int h) implements Shape {\n        public String name() { return \"Triangle\"; }\n        public int area() { return b * h / 2; }\n    }\n\n    public static void main(String[] args) {\n        List<Shape> shapes = List.of(new Rectangle(3, 4), new Square(5), new Triangle(6, 4));\n        int total = 0;\n        for (Shape s : shapes) {\n            System.out.println(s.name() + \" area \" + s.area());\n            total += s.area();\n        }\n        System.out.println(\"total \" + total);\n    }\n}",
    "python": "from abc import ABC, abstractmethod\n\nclass Shape(ABC):\n    @abstractmethod\n    def area(self): ...\n\n    def name(self):\n        return type(self).__name__\n\nclass Rectangle(Shape):\n    def __init__(self, w, h):\n        self.w, self.h = w, h\n    def area(self):\n        return self.w * self.h\n\nclass Square(Rectangle):\n    def __init__(self, s):\n        super().__init__(s, s)\n\nclass Triangle(Shape):\n    def __init__(self, b, h):\n        self.b, self.h = b, h\n    def area(self):\n        return self.b * self.h // 2\n\nshapes = [Rectangle(3, 4), Square(5), Triangle(6, 4)]\ntotal = 0\nfor s in shapes:                    # duck typing: anything with area() would work\n    print(s.name(), \"area\", s.area())\n    total += s.area()\nprint(\"total\", total)",
    "js": "class Rectangle {\n  constructor(w, h) { this.w = w; this.h = h; }\n  name() { return \"Rectangle\"; }\n  area() { return this.w * this.h; }\n}\nclass Square extends Rectangle {\n  constructor(s) { super(s, s); }\n  name() { return \"Square\"; }\n}\nclass Triangle {\n  constructor(b, h) { this.b = b; this.h = h; }\n  name() { return \"Triangle\"; }\n  area() { return (this.b * this.h) / 2; }\n}\n\nconst shapes = [new Rectangle(3, 4), new Square(5), new Triangle(6, 4)];\nlet total = 0;\nfor (const s of shapes) {              // no interfaces: any object with area() works\n  console.log(s.name(), \"area\", s.area());\n  total += s.area();\n}\nconsole.log(\"total\", total);",
    "ts": "interface Shape { name(): string; area(): number }\n\nclass Rectangle implements Shape {\n  w: number;\n  h: number;\n  constructor(w: number, h: number) { this.w = w; this.h = h; }\n  name(): string { return \"Rectangle\"; }\n  area(): number { return this.w * this.h; }\n}\nclass Square extends Rectangle {\n  constructor(s: number) { super(s, s); }\n  name(): string { return \"Square\"; }\n}\nclass Triangle implements Shape {\n  b: number;\n  h: number;\n  constructor(b: number, h: number) { this.b = b; this.h = h; }\n  name(): string { return \"Triangle\"; }\n  area(): number { return (this.b * this.h) / 2; }\n}\n\nconst shapes: Shape[] = [new Rectangle(3, 4), new Square(5), new Triangle(6, 4)];\nlet total = 0;\nfor (const s of shapes) {\n  console.log(s.name(), \"area\", s.area());\n  total += s.area();\n}\nconsole.log(\"total\", total);",
    "rust": "trait Shape {\n    fn name(&self) -> &str;\n    fn area(&self) -> i32;\n}\n\nstruct Rectangle { w: i32, h: i32 }\nstruct Square { s: i32 }\nstruct Triangle { b: i32, h: i32 }\n\nimpl Shape for Rectangle { fn name(&self) -> &str { \"Rectangle\" } fn area(&self) -> i32 { self.w * self.h } }\nimpl Shape for Square { fn name(&self) -> &str { \"Square\" } fn area(&self) -> i32 { self.s * self.s } }\nimpl Shape for Triangle { fn name(&self) -> &str { \"Triangle\" } fn area(&self) -> i32 { self.b * self.h / 2 } }\n\nfn main() {\n    let shapes: Vec<Box<dyn Shape>> = vec![      // dyn Shape: chosen at run time, like a virtual call\n        Box::new(Rectangle { w: 3, h: 4 }),\n        Box::new(Square { s: 5 }),\n        Box::new(Triangle { b: 6, h: 4 }),\n    ];\n    let mut total = 0;\n    for s in &shapes {\n        println!(\"{} area {}\", s.name(), s.area());\n        total += s.area();\n    }\n    println!(\"total {}\", total);\n}"
  },
