    "cpp": "#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s;\n    for (int i = 0; i < 10; i++) {\n        if (i) s += ',';\n        s += to_string(i);                      // += appends in place: cheap\n    }\n    cout << s << endl;\n    cout << \"length \" << s.size() << endl;\n    char next = 'a' + 1;                        // a char is a small integer\n    cout << \"'a' + 1 = \" << next << endl;\n    cout << \"'7' as number = \" << ('7' - '0') << endl;\n}",
    "java": "public class Main {\n    public static void main(String[] args) {\n        StringBuilder sb = new StringBuilder();       // s += x in a loop copies the whole string every time\n        for (int i = 0; i < 10; i++) {\n            if (i > 0) sb.append(',');\n            sb.append(i);\n        }\n        String s = sb.toString();\n        System.out.println(s);\n        System.out.println(\"length \" + s.length());\n        System.out.println(\"'a' + 1 = \" + (char) ('a' + 1));\n        System.out.println(\"'7' as number = \" + ('7' - '0'));\n    }\n}",
